"""Reviewer A deterministic adversarial checks; no integration or neural run."""
from pathlib import Path
import sys, json, math, copy, unittest
from fractions import Fraction as F
from decimal import localcontext
sys.path.insert(0,str(Path(__file__).resolve().parent/'capsule'))
import H3_shorttime_solver as s
import H3_circle_kernel as c
import H3_reference_solver as r
import H3_stability as st
BASE=Path(__file__).resolve().parent
RUN=json.loads((BASE/'capsule/run/result.json').read_text())
OBS=RUN['reference']['observations']
COEFF={k:s.I(**v) for k,v in RUN['reference']['coefficients'].items()}
SAVED=s.load_checkpoint(BASE/'capsule/run/midpoint_checkpoint.json')
KERNEL=c.CircleKernel.from_record(json.loads((BASE/'capsule/run/kernel.json').read_text()))

def exp_bounds(x,terms=180):
    x=F(x)
    if x<0:
        lo,hi=exp_bounds(-x,terms)
        return 1/hi,1/lo
    term=total=F(1)
    for j in range(1,terms+1):
        term=term*x/j; total+=term
    assert x<terms+2
    tail=term*x/(terms+1)/(1-x/(terms+2))
    return total,total+tail

def b_bounds(k,t):
    elo,ehi=exp_bounds(-k*t,40)
    return (1-ehi)/k,(1-elo)/k

def covers(i,lo,hi=None):
    if hi is None: hi=lo
    return F(i.lo)<=lo<=hi<=F(i.hi)

def normal(n):
    return F(0) if n%2 else F(math.factorial(n),2**(n//2)*math.factorial(n//2))

class Attacks(unittest.TestCase):
    def test_interval_corners_and_odd_powers(self):
        cases=[(F(-7,3),F(-1,3)),(F(-5,7),F(11,9)),(F(0),F(0)),(F(2,3),F(5,3))]
        for alo,ahi in cases:
            a=s.I(s.rational(alo).lo,s.rational(ahi).hi)
            for p in range(1,6):
                values=[alo**p,ahi**p]
                if alo<=0<=ahi: values.append(F(0))
                self.assertTrue(covers(a**p,min(values),max(values)))
            for blo,bhi in cases:
                b=s.I(s.rational(blo).lo,s.rational(bhi).hi)
                values=[x*y for x in (alo,ahi) for y in (blo,bhi)]
                self.assertTrue(covers(a*b,min(values),max(values)))
                if not blo<=0<=bhi:
                    values=[x/y for x in (alo,ahi) for y in (blo,bhi)]
                    self.assertTrue(covers(a/b,min(values),max(values)))
        with self.assertRaises(ZeroDivisionError): s.I(1)/s.I(-1,1)
        with self.assertRaises(ValueError): s.I(-1,0).sqrt()

    def test_tanh_transcendental_oracle(self):
        for x in (F(-8),F(-1),F(-1,10**6),F(0),F(1,2),F(8)):
            elo,ehi=exp_bounds(2*x)
            lo,hi=(elo-1)/(elo+1),(ehi-1)/(ehi+1)
            self.assertTrue(covers(s.rational(x).tanh(),lo,hi))

    def test_simpson_sharp_polynomial_constant(self):
        # Integral x^4 on [-h,h] minus Simpson is -4h^5/15;
        # f''''=24, so h^5*24/90 has exactly that magnitude.
        for h in (F(1),F(1,7),F(3,2)):
            integral=2*h**5/5
            quadrature=h/3*(h**4+h**4)
            self.assertEqual(abs(integral-quadrature),h**5*24/90)
        # Integrate |K(v)|=(1-v)^3(1+3v)/72 over [0,1], then double.
        polynomial=[1,0,-6,8,-3]
        self.assertEqual(2*sum(F(a,j+1) for j,a in enumerate(polynomial))/72,F(1,90))

    def test_singular_hermite_correlations(self):
        polynomials=c.hermite_polynomials()
        for rho in (-1,0,1):
            for m in range(8):
                for n in range(8):
                    if rho==0:
                        value=sum(a*normal(i) for i,a in enumerate(polynomials[m]))*sum(b*normal(j) for j,b in enumerate(polynomials[n]))
                    else:
                        value=sum(a*b*(rho**j)*normal(i+j) for i,a in enumerate(polynomials[m]) for j,b in enumerate(polynomials[n]))
                    expected=F(math.factorial(n)*rho**n) if m==n else F(0)
                    self.assertEqual(value,expected)
        self.assertTrue(covers(KERNEL.kernel_enclosure(1),F(KERNEL.v.lo),F(KERNEL.v.hi)))
        self.assertTrue(covers(KERNEL.kernel_enclosure(-1),-F(KERNEL.v.hi),-F(KERNEL.v.lo)))
        self.assertTrue(covers(KERNEL.kernel_enclosure(0),F(0)))

    def test_initial_current_pairing_and_covariance(self):
        # At t=0 true same-coordinate motion is exactly zero. Independent
        # marginals instead give RMS sqrt(2k)>.6 and cannot match this output.
        for key in ('first_rms_true_enclosure','upper_rms_true_enclosure'):
            i=s.I(**OBS[0][key]); self.assertTrue(covers(i,F(0))); self.assertLess(i.hi,s.D('1e-20'))
        self.assertGreater((2*COEFF['k']).sqrt().lo,s.D('.6'))
        g={k:s.I(**v) for k,v in RUN['reference']['moments_g'].items()}
        A=COEFF['alpha']*g['h2s2']/COEFF['q']; B=-COEFF['gamma']*g['s2']
        residual=COEFF['n1sq']-COEFF['q']*(A**2+B**2)
        self.assertGreater(residual.lo,0)
        beta=s.I(**OBS[-1]['beta_diagonal'])
        all_motion=beta*COEFF['n1sq'].sqrt()
        noise_only=beta*(g['s4']*COEFF['v']).sqrt()
        response_only=beta*(g['s4']*COEFF['gamma']**2*COEFF['q']+COEFF['alpha']**2*g['h2s4']).sqrt()
        differences={'noise_only_omission':(all_motion-noise_only).record(),'response_only_omission':(all_motion-response_only).record(),'conditional_source_variance':residual.record()}
        (BASE/'response_attacks.json').write_text(json.dumps(differences,indent=2)+'\n')
        for alt in (noise_only,response_only): self.assertGreater((all_motion-alt).lo,s.D('1e-7'))

    def test_direct_formula_oracle_after_restart(self):
        k=(F(COEFF['k'].lo)+F(COEFF['k'].hi))/2
        for t in (F(0),F(1,10**20),F(1,800),F(1,400),F(3,800),F(1,200)-F(1,10**20),F(1,200)):
            if t<=F(1,400): state=s.advance_checkpoint((F(0),s.I(0),s.I(0),COEFF),t)
            else: state=s.advance_checkpoint(SAVED,t-F(1,400))
            blo,bhi=b_bounds(k,t)
            self.assertTrue(covers(state[1],blo,bhi))
            self.assertTrue(covers(state[2],blo*blo/2,bhi*bhi/2))
            self.assertLess(F(state[1].hi)-F(state[1].lo),2*c.MAX_B_RADIUS)
            en=r.prediction(state,KERNEL,s.I(1),s.I(0))
            self.assertTrue(covers(en,k*blo,k*bhi))
        self.assertEqual(s.checkpoint_decode(s.checkpoint_encode(*SAVED))[1].record(),SAVED[1].record())

    def test_domain_and_precision_attacks(self):
        for duration in (F(-1,1000),F(1,100)):
            with self.assertRaises(ValueError): s.advance_checkpoint(SAVED,duration)
        invalid=copy.deepcopy(s.checkpoint_encode(*SAVED)); invalid['coefficients']['q']={'lo':'0','hi':'.4'}
        with self.assertRaises(ValueError): s.checkpoint_decode(invalid)
        invalid=copy.deepcopy(s.checkpoint_encode(*SAVED)); invalid['state']['b']={'lo':'Infinity','hi':'Infinity'}
        with self.assertRaises(ValueError): s.checkpoint_decode(invalid)
        with localcontext() as context:
            context.prec=30
            with self.assertRaises(ValueError): s.checkpoint_decode(s.checkpoint_encode(*SAVED)|{'certificate':copy.deepcopy(s.checkpoint_encode(*SAVED)['certificate'])}|{'certificate':{'elapsed_time':{'numerator':1,'denominator':400},'horizon':{'numerator':1,'denominator':200},'analytical_origin':'original canonical initialization at t=0','precision_digits':60}})
            with self.assertRaises(ValueError): KERNEL.prediction(s.I('.003'),1,0)
        for box in ((s.I('.6'),s.I('.6')),(s.I('1.1'),s.I(0)),(s.I('-1','1'),s.I('-1','1'))):
            with self.assertRaises(ValueError): KERNEL.prediction_box(s.I('.003'),*box)
        with self.assertRaises(ValueError): KERNEL.prediction(s.I('.006'),1,0)
        for sigma in (s.I('-0.01'),s.I('1.01')):
            with self.assertRaises(ValueError): s.gaussian_moments(sigma,panels=2)
        for n in (0,1,3):
            with self.assertRaises(ValueError): s.gaussian_moments(s.I(0),panels=n)

    def test_stability_coefficients_independently(self):
        # Sum the row/middle/readout velocity coefficient vectors directly.
        a,c0,cut=F(201,100),F(1,50),F(1,5); R=1+c0
        df=[c0*a,c0,F(1)]
        dz=[a,F(1),F(0)]
        dd=[2*c0*a,2*c0,F(1)]
        dq=[a*x for x in dd]; dq[1]+=c0
        d1=dq[:];d1[0]+=2*cut
        row=[2*a*c0*x+2*R*y for x,y in zip(df,d1)]
        mid=[2*c0*x+2*R*y for x,y in zip(df,dd)];mid[0]+=2*R*c0
        read=[2*x+2*R*y for x,y in zip(df,dz)]
        total=[x+y+z for x,y,z in zip(row,mid,read)]
        out=st.comparison_constants(cut)
        self.assertEqual(total,[out['row_coefficient'],out['middle_coefficient'],out['readout_coefficient']])
        lo,hi=exp_bounds(F(1,100),40)
        slo,shi=st.exp_bounds(F(1,100))
        self.assertLessEqual(slo,lo);self.assertGreaterEqual(shi,hi)

if __name__=='__main__': unittest.main(verbosity=2)

